:host {
    display: block;
    --blue: #0176d3;
    --blue-ink: #0b5cab;
    --ink: #181818;
    --muted: #5c5c5c;
    --line: #e5e5e5;
    --ok: #2e844a;
    --ok-soft: #ebf7e6;
    --bad: #ba0517;
    --bad-soft: #fef1ee;
    --warn-soft: #fef1cd;
}

.rr-review { color: var(--ink); font-size: 14px; line-height: 1.5; display: flex; flex-direction: column; gap: 14px; }
.rr-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 12.5px; }
.rr-muted { color: var(--muted); margin: 0; }
.rr-small { font-size: 12.5px; }
.rr-pad { padding: 4px 2px; }
.rr-pre { white-space: pre-wrap; }
.rr-top-gap { margin-top: 16px; }
.rr-h3 { margin: 0; font-size: 15px; font-weight: 700; }

/* header */
.rr-head { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px; align-items: flex-start; }
.rr-head-main { min-width: 0; flex: 1 1 560px; }
.rr-title-row { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
.rr-req-no { font-weight: 700; color: var(--muted); }
.rr-title { margin: 0; font-size: 20px; font-weight: 700; line-height: 1.3; }
.rr-meta { margin: 4px 0 0; color: var(--muted); display: flex; flex-wrap: wrap; gap: 6px; }
.rr-links a { margin-right: 12px; }
.rr-head-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.rr-back { margin-bottom: 6px; }

.rr-btn {
    display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 14px;
    border: 1px solid #c9c9c9; border-radius: 6px; background: #fff; color: var(--blue-ink);
    font: inherit; font-weight: 600; cursor: pointer; white-space: nowrap;
}
.rr-btn:hover { background: #f7f9fc; }
.rr-btn:focus-visible, .rr-tab:focus-visible, .rr-file:focus-visible, .rr-link-btn:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
.rr-btn-brand { background: var(--ok); border-color: var(--ok); color: #fff; }
.rr-btn-brand:hover { background: #22683a; }
.rr-btn-danger { color: var(--bad); border-color: #f0b8b0; }
.rr-btn-quiet { border-color: transparent; color: var(--muted); }
.rr-link-btn { background: none; border: 0; padding: 0; color: var(--blue-ink); cursor: pointer; font: inherit; }

.rr-pill { display: inline-block; padding: 2px 10px; border-radius: 12px; font-size: 12px; font-weight: 700; white-space: nowrap; }
.rr-pill-ok { background: var(--ok-soft); color: #194e31; }
.rr-pill-bad { background: var(--bad-soft); color: #8e030f; }
.rr-pill-ready { background: #eef4ff; color: var(--blue-ink); }
.rr-pill-busy { background: var(--warn-soft); color: #5c3a00; }
.rr-pill-muted { background: #f3f3f3; color: var(--muted); }

/* progress path (chevrons) */
.rr-path { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px 0; }
.rr-step {
    flex: 1 1 120px; min-width: 0; display: flex; align-items: center; gap: 8px; height: 50px;
    padding: 0 10px 0 24px; margin-right: -8px; background: #e5e5e5; color: var(--ink);
    clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 50%, calc(100% - 16px) 100%, 0 100%, 16px 50%);
}
.rr-step-first { padding-left: 14px; clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 50%, calc(100% - 16px) 100%, 0 100%); border-radius: 8px 0 0 8px; }
.rr-step:last-child { margin-right: 0; }
.rr-path-icon {
    flex: none; width: 24px; height: 24px; border-radius: 12px; display: flex; align-items: center; justify-content: center;
    font-size: 12px; font-weight: 700; background: rgba(255, 255, 255, 0.85); color: var(--muted);
}
.rr-path-text { display: flex; flex-direction: column; min-width: 0; line-height: 1.25; }
.rr-path-label { font-weight: 700; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-path-note { font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; opacity: 0.9; }
.rr-step-ok { background: var(--ok); color: #fff; }
.rr-step-ok .rr-path-icon { color: var(--ok); }
.rr-step-bad { background: var(--bad); color: #fff; }
.rr-step-bad .rr-path-icon { color: var(--bad); }
.rr-step-cur { background: var(--blue); color: #fff; }
.rr-step-cur .rr-path-icon { color: var(--blue); }
.rr-step-skip { background: #f3f3f3; color: #939393; }
.rr-step-todo .rr-path-note { color: var(--muted); }

/* failure panel */
.rr-fail { border: 1px solid #f0b8b0; border-left: 5px solid var(--bad); background: var(--bad-soft); border-radius: 10px; padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; }
.rr-fail-head { display: flex; gap: 12px; align-items: flex-start; }
.rr-fail-icon { flex: none; width: 28px; height: 28px; border-radius: 14px; background: var(--bad); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 700; }
.rr-fail-titles { min-width: 0; }
.rr-fail-title { margin: 0; font-size: 16px; font-weight: 700; color: #8e030f; }
.rr-fail-sub { margin: 2px 0 0; color: #5c1a14; }
.rr-fail-list { list-style: none; margin: 0; padding: 0; background: #fff; border: 1px solid #f6d3cd; border-radius: 8px; }
.rr-fail-list li { display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 8px 12px; border-bottom: 1px solid #f9e3df; }
.rr-fail-list li:last-child { border-bottom: 0; }
.rr-fail-where { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 12.5px; font-weight: 600; color: #8e030f; }
.rr-fail-text { flex: 1 1 260px; min-width: 0; }
.rr-fail-next { margin: 0; }
.rr-fail-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.rr-fail-actions a.btn { text-decoration: none; }
.rr-btn-blue { background: var(--blue); border-color: var(--blue); color: #fff; }
.rr-btn-blue:hover { background: var(--blue-ink); }
.rr-btn-small { height: 28px; padding: 0 10px; font-size: 12.5px; }
.rr-btn:disabled { opacity: 0.55; cursor: default; }

/* editor */
.rr-editor { display: flex; flex-direction: column; gap: 10px; padding: 12px; }
.rr-code {
    width: 100%; min-height: 420px; resize: vertical; border: 1px solid #c9c9c9; border-radius: 6px; padding: 10px;
    font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 12.5px; line-height: 1.55; tab-size: 4; white-space: pre; overflow: auto;
}
.rr-code:focus { outline: 2px solid var(--blue); outline-offset: 1px; }

.rr-msg { margin: 0; padding: 10px 12px; border-radius: 8px; font-size: 13px; }
.rr-msg-info { background: #f3f9ff; color: #1b3d5f; }
.rr-msg-bad { background: var(--bad-soft); color: #8e030f; }
.rr-msg-warn { background: var(--warn-soft); color: #5c3a00; margin: 8px 0; }

.rr-card { background: #fff; border: 1px solid var(--line); border-radius: 10px; padding: 16px; }
.rr-action-card { border-color: var(--blue); display: flex; flex-direction: column; gap: 10px; }
.rr-row-end { display: flex; justify-content: flex-end; gap: 8px; }

/* tabs */
.rr-tabs { display: flex; flex-wrap: wrap; gap: 2px; border-bottom: 1px solid var(--line); }
.rr-tab {
    background: none; border: 0; border-bottom: 3px solid transparent; padding: 8px 12px; font: inherit;
    font-weight: 600; color: var(--muted); cursor: pointer; margin-bottom: -1px;
}
.rr-tab-on { color: var(--ink); border-bottom-color: var(--blue); }

/* files and diff */
.rr-files-layout { display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-start; }
.rr-file-list { list-style: none; margin: 0; padding: 0; flex: 1 1 240px; max-width: 320px; display: flex; flex-direction: column; gap: 2px; max-height: 560px; overflow: auto; }
.rr-file {
    width: 100%; text-align: left; background: none; border: 1px solid transparent; border-radius: 6px; padding: 6px 8px;
    display: grid; grid-template-columns: 1fr auto; gap: 0 8px; font: inherit; cursor: pointer; color: var(--ink);
}
.rr-file:hover { background: #f7f9fc; }
.rr-file-on { border-color: var(--blue); background: #eef4ff; }
.rr-file-name { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-file-folder { grid-column: 1; font-size: 12px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-file-stats { grid-column: 2; grid-row: 1 / span 2; align-self: center; font-size: 12px; font-family: ui-monospace, Menlo, Consolas, monospace; }
.rr-file-removed .rr-file-name { text-decoration: line-through; color: var(--bad); }
.rr-file-added .rr-file-name { color: var(--ok); }
.rr-adds { color: var(--ok); }
.rr-dels { color: var(--bad); }

.rr-diff-pane { flex: 999 1 480px; min-width: 0; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.rr-diff-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 6px 12px; min-height: 40px; background: #f7f7f7; border-bottom: 1px solid var(--line); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-diff-scroll { overflow: auto; max-height: 560px; }
.rr-diff { border-collapse: collapse; width: 100%; font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 12px; line-height: 1.55; }
.rr-diff td { padding: 0 8px; vertical-align: top; }
.rr-ln { width: 1%; text-align: right; color: #939393; user-select: none; white-space: nowrap; }
.rr-sg { width: 1%; user-select: none; }
.rr-tx { white-space: pre; }
.rr-dl-add { background: #e6ffec; }
.rr-dl-add .rr-sg { color: var(--ok); }
.rr-dl-del { background: #ffebe9; }
.rr-dl-del .rr-sg { color: var(--bad); }
.rr-dl-hunk { background: #eef4ff; color: var(--blue-ink); }
.rr-dl-note { color: var(--muted); }

/* scan */
.rr-counts { display: flex; flex-wrap: wrap; gap: 8px; margin: 10px 0; }
.rr-count { padding: 4px 10px; border-radius: 8px; background: #f3f3f3; font-size: 13px; }
.rr-count-critical { background: #fef1ee; color: #8e030f; }
.rr-count-high { background: #fff1e5; color: #8c3b00; }
.rr-count-moderate { background: var(--warn-soft); color: #5c3a00; }
.rr-sev { display: inline-block; padding: 1px 8px; border-radius: 10px; font-size: 12px; font-weight: 700; background: #f3f3f3; }
.rr-sev-critical { background: #ba0517; color: #fff; }
.rr-sev-high { background: #fe9339; color: #3a1a00; }
.rr-sev-moderate { background: #fcc003; color: #3a2a00; }

.rr-table-wrap { overflow-x: auto; }
.rr-grid { width: 100%; border-collapse: collapse; font-size: 13px; margin: 8px 0; }
.rr-grid th { text-align: left; font-size: 12px; color: var(--muted); font-weight: 600; padding: 6px 8px; border-bottom: 1px solid var(--line); background: #fafaf9; }
.rr-grid td { padding: 6px 8px; border-bottom: 1px solid var(--line); vertical-align: top; }

.rr-checks { display: flex; flex-direction: column; gap: 18px; }
.rr-check { display: flex; flex-direction: column; gap: 6px; }
.rr-check-head { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }

.rr-chg { font-weight: 700; font-size: 12px; }
.rr-chg-new { color: var(--ok); }
.rr-chg-deleted { color: var(--bad); }
.rr-chg-modified { color: var(--blue-ink); }

.rr-kv { display: grid; grid-template-columns: max-content 1fr; gap: 6px 16px; margin: 0; }
.rr-kv dt { color: var(--muted); }
.rr-kv dd { margin: 0; }

.rr-diff-path { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
